<script setup lang="ts">
import {ref} from 'vue';import InputText from 'primevue/inputtext';import Button from 'primevue/button';import DataTable from 'primevue/datatable';import Column from 'primevue/column';import {api} from '../lib/api';import {useQuery} from '../composables/useQuery';import {date,initials} from '../lib/types';import QueryState from '../components/QueryState.vue';
const search=ref(''),appliedSearch=ref(''),cursor=ref<string|null>(null),page=ref(1);
const previous:(string|null)[]=[];
const {data,loading,error,refresh}=useQuery(()=>api('/admin/audit-logs?'+new URLSearchParams({q:appliedSearch.value,pageSize:'30',...(cursor.value?{cursor:cursor.value}:{})})),15000);
function reset(){appliedSearch.value=search.value.trim();cursor.value=null;previous.length=0;page.value=1;void refresh();}
function paginate(forward:boolean){if(loading.value)return;if(forward){if(!data.value?.nextCursor)return;previous.push(cursor.value);cursor.value=data.value.nextCursor;page.value++;}else{if(page.value===1)return;cursor.value=previous.pop()??null;page.value--;}void refresh();}
</script>
<template><div class="page-heading"><div><div class="eyebrow">TRUY VẾT & KIỂM SOÁT</div><h1>Nhật ký hoạt động<span class="green-text">.</span></h1><p>Mỗi quyết định đều có người thực hiện, thời điểm và lý do.</p></div><span class="date-pill"><i class="pi pi-lock"></i>Chỉ đọc · Append-only</span></div><section class="panel"><form class="filter-bar" @submit.prevent="reset"><span class="search-input"><i class="pi pi-search"></i><InputText v-model="search" placeholder="Tìm thao tác hoặc người thực hiện…" aria-label="Tìm nhật ký"/></span><Button type="submit" label="Tìm nhật ký" icon="pi pi-search" outlined/><Button label="Về mới nhất" text severity="secondary" @click="reset"/></form><QueryState :loading="loading" :error="error" @retry="refresh"/><DataTable v-if="data" :value="data.items" class="grap-table"><template #empty><div class="table-empty">Không có nhật ký phù hợp.</div></template><Column header="THỜI ĐIỂM"><template #body="{data:d}">{{date(d.createdAt)}}</template></Column><Column header="NGƯỜI THỰC HIỆN"><template #body="{data:d}"><div class="person-cell"><span class="avatar small mint">{{initials(d.actorName)}}</span><strong>{{d.actorName}}</strong></div></template></Column><Column header="THAO TÁC"><template #body="{data:d}"><code class="action-code">{{d.action}}</code></template></Column><Column header="LÝ DO"><template #body="{data:d}"><span class="audit-reason">{{d.reason||'—'}}</span></template></Column><Column header="TRACE"><template #body="{data:d}"><span class="trace-id" :title="d.traceId">{{d.traceId?.slice(0,12)||'—'}}</span></template></Column></DataTable><div class="pagination"><span>Trang {{page}} · {{data?.items.length??0}} bản ghi</span><div><Button label="Trang trước" icon="pi pi-arrow-left" text severity="secondary" :disabled="loading||page===1" @click="paginate(false)"/><Button label="Tải trang tiếp" icon="pi pi-arrow-right" icon-pos="right" text :disabled="loading||!data?.nextCursor" @click="paginate(true)"/></div></div></section></template>
